DO $move$ BEGIN IF to_regprocedure('shroud_private.create_secret_for_api_token(uuid, uuid, uuid, text, text, boolean, text, integer, uuid)') IS NULL THEN ALTER FUNCTION public.create_secret_for_api_token(uuid, uuid, uuid, text, text, boolean, text, integer, uuid) SET SCHEMA shroud_private; END IF; END $move$;
REVOKE ALL ON FUNCTION shroud_private.create_secret_for_api_token(uuid, uuid, uuid, text, text, boolean, text, integer, uuid) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.create_secret_for_api_token(p_team_id uuid, p_project_id uuid, p_environment_id uuid, p_key text, p_description text, p_is_required boolean, p_encrypted_value text, p_encryption_version integer, p_created_by uuid, p_token_hash text DEFAULT NULL)
RETURNS TABLE(id uuid, key text, description text, is_required boolean, version integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE actor uuid;
BEGIN
  actor := shroud_private.assert_token(p_token_hash, p_team_id, 'secrets:write');

  IF p_created_by IS DISTINCT FROM actor THEN RAISE EXCEPTION 'Invalid actor' USING ERRCODE = '42501'; END IF;
  IF p_key IS NULL OR p_key !~ '^[A-Za-z_][A-Za-z0-9_]*$' THEN RAISE EXCEPTION 'Invalid key'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.team_members m WHERE m.team_id = p_team_id AND m.user_id = actor AND m.role IN ('owner','admin','developer')) THEN
    RAISE EXCEPTION 'Insufficient write access' USING ERRCODE = '42501';
  END IF;
  -- Serialize concurrent pushes for the same environment/key, including first creation.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_environment_id::text || ':' || p_key, 0));
  PERFORM 1 FROM public.secrets s WHERE s.environment_id = p_environment_id AND s.key = p_key FOR UPDATE;

  RETURN QUERY SELECT * FROM shroud_private.create_secret_for_api_token(p_team_id, p_project_id, p_environment_id, p_key, p_description, p_is_required, p_encrypted_value, p_encryption_version, p_created_by);
END; $$;
REVOKE ALL ON FUNCTION public.create_secret_for_api_token(uuid, uuid, uuid, text, text, boolean, text, integer, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_secret_for_api_token(uuid, uuid, uuid, text, text, boolean, text, integer, uuid, text) TO anon, authenticated;


DO $move$ BEGIN IF to_regprocedure('shroud_private.create_secret_with_version(uuid, text, text, boolean, text, integer, uuid)') IS NULL THEN ALTER FUNCTION public.create_secret_with_version(uuid, text, text, boolean, text, integer, uuid) SET SCHEMA shroud_private; END IF; END $move$;
REVOKE ALL ON FUNCTION shroud_private.create_secret_with_version(uuid, text, text, boolean, text, integer, uuid) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.create_secret_with_version(p_environment_id uuid, p_key text, p_description text, p_is_required boolean, p_encrypted_value text, p_encryption_version integer, p_created_by uuid) RETURNS public.secrets
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE result public.secrets;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_created_by THEN
    RAISE EXCEPTION 'Invalid actor' USING ERRCODE='42501'; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.environments e JOIN public.project_members m ON m.project_id=e.project_id
    WHERE e.id=p_environment_id AND m.user_id=auth.uid() AND m.role IN ('owner','admin','developer')) THEN
    RAISE EXCEPTION 'Insufficient project access' USING ERRCODE='42501'; END IF;
  IF p_key IS NULL OR p_key !~ '^[A-Za-z_][A-Za-z0-9_]*$' THEN RAISE EXCEPTION 'Invalid key'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_environment_id::text || ':' || p_key, 0));
  IF EXISTS (SELECT 1 FROM public.secrets s WHERE s.environment_id=p_environment_id AND s.key=p_key) THEN
    RAISE EXCEPTION 'Key already exists' USING ERRCODE='23505'; END IF;

  result := shroud_private.create_secret_with_version(p_environment_id, p_key, p_description, p_is_required, p_encrypted_value, p_encryption_version, p_created_by);

  RETURN result;
END; $$;
REVOKE ALL ON FUNCTION public.create_secret_with_version(uuid, text, text, boolean, text, integer, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_secret_with_version(uuid, text, text, boolean, text, integer, uuid) TO authenticated;


DO $move$ BEGIN IF to_regprocedure('shroud_private.create_secret_version(uuid, text, integer, uuid)') IS NULL THEN ALTER FUNCTION public.create_secret_version(uuid, text, integer, uuid) SET SCHEMA shroud_private; END IF; END $move$;
REVOKE ALL ON FUNCTION shroud_private.create_secret_version(uuid, text, integer, uuid) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.create_secret_version(p_secret_id uuid, p_encrypted_value text, p_encryption_version integer, p_created_by uuid) RETURNS public.secret_versions
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE result public.secret_versions;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_created_by THEN
    RAISE EXCEPTION 'Invalid actor' USING ERRCODE='42501'; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.secrets s JOIN public.environments e ON e.id=s.environment_id
    JOIN public.project_members m ON m.project_id=e.project_id
    WHERE s.id=p_secret_id AND m.user_id=auth.uid() AND m.role IN ('owner','admin','developer')) THEN
    RAISE EXCEPTION 'Insufficient project access' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.secrets s WHERE s.id=p_secret_id FOR UPDATE;

  result := shroud_private.create_secret_version(p_secret_id, p_encrypted_value, p_encryption_version, p_created_by);

  RETURN result;
END; $$;
REVOKE ALL ON FUNCTION public.create_secret_version(uuid, text, integer, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_secret_version(uuid, text, integer, uuid) TO authenticated;


