CREATE OR REPLACE FUNCTION public.create_team_invitation(p_team_id uuid, p_invited_by uuid, p_role public.team_role, p_expires_at timestamptz) RETURNS TABLE(id uuid, team_id uuid, role public.team_role, token text, invite_code text, expires_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$

BEGIN
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_invited_by THEN
    RAISE EXCEPTION 'Invalid actor' USING ERRCODE='42501'; END IF;

  IF p_role NOT IN ('admin','developer','viewer') OR p_expires_at IS NULL OR p_expires_at <= now() THEN
    RAISE EXCEPTION 'Invalid invitation role or expiration'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.team_members m WHERE m.team_id=p_team_id AND m.user_id=auth.uid()
    AND (m.role='owner' OR (m.role='admin' AND p_role IN ('developer','viewer')))) THEN
    RAISE EXCEPTION 'Insufficient team access' USING ERRCODE='42501'; END IF;
  PERFORM shroud_private.log_event(p_team_id, 'team.invitation_created', 'team', p_team_id);

  RETURN QUERY SELECT * FROM shroud_private.create_team_invitation(p_team_id, p_invited_by, p_role, p_expires_at);

END; $$;
REVOKE ALL ON FUNCTION public.create_team_invitation(uuid, uuid, public.team_role, timestamptz) FROM PUBLIC, anon;
